#!/usr/bin/env bash
# Puts the Gmail App Password on the server as mail.local.php (docs/MAIL.md),
# from the OWNIFY_MAIL_APP_PASSWORD secret, over the deploy's own SFTP login.
# Run by .github/workflows/deploy.yml; never uploaded (.github is not in ./*).
#
#   MAIL_LOCATION=private  (default) <web root>/../private/mail.local.php —
#                          outside public_html; the folder 700, the file 600
#   MAIL_LOCATION=config   <web root>/config/mail.local.php — only when chosen;
#                          then checked to give nothing over HTTPS
#
# Nothing is guessed: the web root is SFTP_REMOTE_PATH, it must end in
# public_html and hold Ownify, and the folder above it must be listable and
# hold public_html — otherwise this stops and says which. It never falls back
# to the other location by itself.
#
# Never printed: the password (masked, and only ever in a 600 file in a 700
# temp folder that is removed), the key, the paths (masked).
#
# Needs: SFTP_SERVER SFTP_USERNAME SFTP_PRIVATE_KEY SFTP_REMOTE_PATH
#        OWNIFY_MAIL_APP_PASSWORD; optional SFTP_PORT (22), MAIL_LOCATION,
#        PUBLIC_URL (https://ownify.acits.nl), SFTP_KNOWN_HOSTS_FILE.
set -euo pipefail
umask 077

fail() { echo "::error title=Mail password not provisioned::$1"; exit 1; }
note() { echo "  $1"; }

for v in SFTP_SERVER SFTP_USERNAME SFTP_PRIVATE_KEY SFTP_REMOTE_PATH OWNIFY_MAIL_APP_PASSWORD; do
    [ -n "${!v:-}" ] || fail "$v is empty."
done
location="${MAIL_LOCATION:-private}"
case "$location" in private|config) ;; *) fail "MAIL_LOCATION must be private or config." ;; esac
public_url="${PUBLIC_URL:-https://ownify.acits.nl}"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# --- the password: Google shows it as four groups of four letters --------
password="$(printf '%s' "$OWNIFY_MAIL_APP_PASSWORD" | tr -d '[:space:]')"
echo "::add-mask::$password"
[[ "$password" =~ ^[a-z]{16}$ ]] \
    || fail "OWNIFY_MAIL_APP_PASSWORD is not the shape of a Gmail App Password (16 letters a-z; spaces are fine). Not uploaded."

# --- the SFTP login, as the deploy's ------------------------------------
printf '%s\n' "$SFTP_PRIVATE_KEY" > "$work/key"
known="${SFTP_KNOWN_HOSTS_FILE:-$work/known_hosts}"
sftp_run() {   # sftp_run <batch file>  — prints sftp's own output
    sftp -q -b "$1" -i "$work/key" -P "${SFTP_PORT:-22}" \
        -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile="$known" \
        -o LogLevel=ERROR "$SFTP_USERNAME@$SFTP_SERVER"
}

# --- where things are ---------------------------------------------------
root="${SFTP_REMOTE_PATH%/}"
parent="$(dirname "$root")"
echo "::add-mask::$root"
echo "::add-mask::$parent"
[ "$(basename "$root")" = "public_html" ] \
    || fail "SFTP_REMOTE_PATH does not end in public_html, so the folder beside it cannot be known. Nothing uploaded."

printf 'ls "%s/config/mail.php"\n' "$root" > "$work/b-root"
sftp_run "$work/b-root" > /dev/null 2>&1 \
    || fail "Ownify's config/mail.php is not at SFTP_REMOTE_PATH: is it the site's web root? Nothing uploaded."
note "web root: public_html, with Ownify's config/mail.php"

# --- the file (the same 404 guard as config/mail.local.php.example) -----
cat > "$work/mail.local.php" <<PHP
<?php
/**
 * The Gmail App Password (docs/MAIL.md). Written by the deploy from the
 * GitHub Actions secret OWNIFY_MAIL_APP_PASSWORD — change the secret and
 * deploy again; do not edit this file.
 */
declare(strict_types=1);

if (PHP_SAPI !== 'cli' && realpath((string) (\$_SERVER['SCRIPT_FILENAME'] ?? '')) === __FILE__) {
    http_response_code(404);
    exit;
}

return ['password' => '$password'];
PHP
chmod 600 "$work/mail.local.php"

if [ "$location" = "private" ]; then
    dir="$parent/private"

    printf 'ls -la "%s"\n' "$parent" > "$work/b-parent"
    if ! sftp_run "$work/b-parent" > "$work/parent.txt" 2>/dev/null; then
        fail "The SFTP account cannot open the folder above public_html, so private/ cannot be written. Nothing uploaded. See docs/MAIL.md (Provisioning) for the choice between asking the host and MAIL_LOCATION=config."
    fi
    grep -Eq '[[:space:]](.*/)?public_html/?$' "$work/parent.txt" \
        || fail "The folder above SFTP_REMOTE_PATH does not hold public_html as expected. Nothing uploaded."
    note "the folder above public_html: reachable"

    # The folder first, 700, so nothing in it is ever readable by others —
    # not even for the moment the upload takes.
    cat > "$work/b-up" <<SFTP
-mkdir "$dir"
chmod 700 "$dir"
put -p "$work/mail.local.php" "$dir/mail.local.php.new"
chmod 600 "$dir/mail.local.php.new"
rename "$dir/mail.local.php.new" "$dir/mail.local.php"
SFTP
    if ! sftp_run "$work/b-up" > /dev/null 2> "$work/up.err"; then
        # An older server cannot rename over a file: remove it, then rename.
        cat > "$work/b-up2" <<SFTP
-rm "$dir/mail.local.php"
rename "$dir/mail.local.php.new" "$dir/mail.local.php"
SFTP
        sftp_run "$work/b-up2" > /dev/null 2>&1 \
            || { printf 'rm "%s/mail.local.php.new"\n' "$dir" > "$work/b-clean"; sftp_run "$work/b-clean" > /dev/null 2>&1 || true;
                 fail "Could not write private/mail.local.php (create, chmod or rename refused by the server). Nothing left behind."; }
    fi
    target="$dir/mail.local.php"
    printf 'ls -la "%s"\nls -la "%s"\n' "$parent" "$dir" > "$work/b-check"
else
    target="$root/config/mail.local.php"
    cat > "$work/b-up" <<SFTP
put -p "$work/mail.local.php" "$target.new"
chmod 600 "$target.new"
rename "$target.new" "$target"
SFTP
    if ! sftp_run "$work/b-up" > /dev/null 2>&1; then
        printf -- '-rm "%s"\nrename "%s.new" "%s"\n' "$target" "$target" "$target" > "$work/b-up2"
        sftp_run "$work/b-up2" > /dev/null 2>&1 || fail "Could not write config/mail.local.php."
    fi
    printf 'ls -la "%s/config"\n' "$root" > "$work/b-check"
fi

# --- check what is there now -------------------------------------------
sftp_run "$work/b-check" > "$work/check.txt" 2>/dev/null || fail "Uploaded, but could not list it to check."
file_mode="$(grep -E '[[:space:]](.*/)?mail\.local\.php$' "$work/check.txt" | awk '{print $1}' | head -1)"
[ -n "$file_mode" ] || fail "mail.local.php is not there after the upload."
[ "$file_mode" = "-rw-------" ] || fail "mail.local.php is $file_mode, not -rw------- (600): the server refused chmod."
note "mail.local.php: $file_mode (600)"
if [ "$location" = "private" ]; then
    dir_mode="$(grep -E '[[:space:]](.*/)?private/?$' "$work/check.txt" | awk '{print $1}' | head -1)"
    [ "$dir_mode" = "drwx------" ] || fail "private/ is $dir_mode, not drwx------ (700): the server refused chmod."
    note "private/: $dir_mode (700), outside public_html"
fi

# --- under the web root: prove it gives nothing over HTTPS --------------
if [ "$location" = "config" ]; then
    code="$(curl -s -o "$work/http.txt" -w '%{http_code}' "$public_url/config/mail.local.php" || echo 000)"
    if grep -qF "$password" "$work/http.txt" 2>/dev/null; then
        fail "config/mail.local.php is READABLE over HTTPS. Remove it at once (or rotate the App Password) and use MAIL_LOCATION=private."
    fi
    [ "$code" = "404" ] || [ ! -s "$work/http.txt" ] \
        || fail "config/mail.local.php answers $code with content over HTTPS; check the server."
    note "over HTTPS config/mail.local.php gives $code and nothing else"
fi

echo "Mail password provisioned at $location/mail.local.php."
